      331:         /* File is either not open, or not opened for read */
      332: 
      333:         ret = -1;
      334:         errno = EBADF;
      335:     }
      336:     else if (buf_off[fd] + size > buf_size[fd])
      337:     {
      338:         ret = 0; /* EOF */
      339:     }
      340:     else
      341:     {
      342:         memcpy(clnt_buf, (void *)(buf[fd] + buf_off[fd]), size);
      343:         buf_off[fd] = buf_off[fd] + size;
      344:         ret = size;
      345:     }
      346: 
      347:     return (ret);
      348: }
